// APOGEX finite objective pool. A flag has exactly one physical location at a time.
export const FACTIONS=[{id:0,name:'ORANGE',color:'#f79442',symbol:'▲'},{id:1,name:'CYAN',color:'#53d3db',symbol:'●'},{id:2,name:'VIOLET',color:'#a486d4',symbol:'◆'},{id:3,name:'LIME',color:'#b9d75b',symbol:'■'}];
export const FLAG_SITES=[[-17,-14],[-8,-18],[3,-18],[14,-14],[-20,-3],[-9,-5],[6,-6],[19,-2],[-17,10],[-6,13],[6,12],[18,10]];
export const LANDING_BAYS=[[0,0,58],[-58,0,-30],[58,0,-30],[0,0,-62]];
export const UPGRADES=[{id:'weapons',name:'Heavy dorsal turret',cost:1100,mass:75,power:1.8,cargo:0,fuel:0,description:'Higher damage, but more mass and electrical demand.'},{id:'cargo',name:'Expanded sample racks',cost:950,mass:80,power:.15,cargo:2,fuel:0,description:'Carry eight flags instead of six. More cargo capacity adds dry mass.'},{id:'reserve',name:'Reserve propellant tank',cost:450,mass:20,power:0,cargo:0,fuel:20,description:'Adds 20 kg of propellant and 20 kg to wet mass.'}];
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const dist=(a,b)=>Math.hypot(a[0]-b[0],a[2]-b[2]);
export function createScienceMatch(seed=1){return {seed,time:0,limit:840,over:false,reason:'',winner:null,flags:FLAG_SITES.map(([x,z],i)=>({id:i,site:i,state:'site',planet:'B',position:[x,1,z],owner:null,carrier:null,stage:0,progress:0,scanner:null})),teams:FACTIONS.map((f,i)=>({...f,credits:4800,ai:i!==0,progress:0,elapsed:0,pace:500+i*30,finished:false,phase:'building',phaseTime:0,planet:'A',delivered:0,onboard:0,hull:2000,capacity:6,eliminated:false,position:[...LANDING_BAYS[i]],botPosition:[...LANDING_BAYS[i]],target:null,carrying:null,buildDuration:155+((seed+i*37)%40),travelDuration:85+i*7,cycles:0})),wrecks:[],events:[]};}
export function flagsAtSites(m){return m.flags.filter(f=>f.state==='site').length;}
export function flagCounts(m,team){return {sites:flagsAtSites(m),onboard:m.flags.filter(f=>f.state==='onboard'&&f.owner===team).length,carried:m.flags.filter(f=>f.state==='carried'&&f.owner===team).length,delivered:m.flags.filter(f=>f.state==='delivered'&&f.owner===team).length,loose:m.flags.filter(f=>f.state==='ground'||f.state==='wreck').length};}
export function conservation(m){return m.flags.length===12&&new Set(m.flags.map(f=>f.id)).size===12&&m.flags.every(f=>['site','carried','ground','onboard','delivered','wreck'].includes(f.state));}
function alive(m,team){return Number.isInteger(team)&&m.teams[team]&&!m.teams[team].eliminated&&!m.over;}
// Claiming a flag is one continuous 5 second hold, split into scan / stabilize / extract beats.
export const SCAN_DURATIONS=[1.7,1.6,1.7];export const SCAN_TOTAL=SCAN_DURATIONS.reduce((a,b)=>a+b,0);
export function scanFraction(f){if(!f||f.state!=='site')return 0;let done=0;for(let i=0;i<Math.min(3,f.stage||0);i++)done+=SCAN_DURATIONS[i];return Math.min(1,(done+(f.progress||0)*SCAN_DURATIONS[Math.min(2,f.stage||0)])/SCAN_TOTAL);}
export function scanFlag(m,id,team,role,dt,distance,aligned=true,powered=false,{anyRole=false}={}){const f=m.flags.find(f=>f.id===id);if(!alive(m,team)||(!anyRole&&role!==3)||!f||f.state!=='site'||distance>3.8||!aligned||m.teams[team].planet!=='B'||m.flags.some(f=>f.state==='carried'&&f.carrier===role&&f.owner===team))return false;if(f.scanner!==null&&f.scanner!==team){f.progress=Math.max(0,f.progress-dt*.5);if(f.progress>0)return false;f.stage=0;}f.scanner=team;const durations=SCAN_DURATIONS;f.progress=clamp(f.progress+Math.max(0,dt)*(powered?1.3:1)/durations[f.stage],0,1);if(f.progress>=1){f.progress=0;f.stage++;if(f.stage>=3){f.state='carried';f.owner=team;f.carrier=role;f.scanner=null;f.planet='B';m.teams[team].carrying=id;m.events.push({time:m.time,text:FACTIONS[team].name+' extracted Science Flag '+(id+1)});}}return true;}
export function dropFlag(m,team,role,position,planet='B'){const f=m.flags.find(f=>f.state==='carried'&&f.owner===team&&f.carrier===role);if(!f)return false;f.state='ground';f.planet=planet;f.position=[...position];f.owner=null;f.carrier=null;m.teams[team].carrying=null;return true;}
export function recoverFlag(m,id,team,role,distance,planet='B'){const f=m.flags.find(f=>f.id===id);if(!alive(m,team)||!f||!['ground','wreck'].includes(f.state)||f.planet!==planet||distance>3.8||m.flags.some(f=>f.state==='carried'&&f.owner===team&&f.carrier===role))return false;f.state='carried';f.owner=team;f.carrier=role;m.teams[team].carrying=id;return true;}
export function loadFlag(m,team,role,distance){const t=m.teams[team],f=m.flags.find(f=>f.state==='carried'&&f.owner===team&&f.carrier===role);if(!alive(m,team)||!f||distance>4.5||t.planet!=='B'||flagCounts(m,team).onboard>=t.capacity)return false;f.state='onboard';f.carrier=null;f.planet='ship';t.carrying=null;t.onboard=flagCounts(m,team).onboard;return true;}
export function deliverFlag(m,team,distance){const t=m.teams[team];if(!alive(m,team)||t.planet!=='A'||!['docked','delivering'].includes(t.phase)||distance>5)return false;const f=m.flags.find(f=>f.state==='onboard'&&f.owner===team);if(!f)return false;f.state='delivered';f.planet='A';f.position=[0,1,39];f.carrier=null;t.delivered=flagCounts(m,team).delivered;t.onboard=flagCounts(m,team).onboard;m.events.push({time:m.time,text:t.name+' delivered Science Flag '+(f.id+1)});return true;}
export function recoverWreckFlag(m,id,team,distance){const f=m.flags.find(f=>f.id===id),t=m.teams[team];if(!alive(m,team)||!f||f.state!=='wreck'||f.planet!=='space'||t.planet!=='space'||distance>4.5||flagCounts(m,team).onboard>=t.capacity)return false;f.state='onboard';f.planet='ship';f.owner=team;f.carrier=null;t.onboard=flagCounts(m,team).onboard;return true;}
export function eliminateCrew(m,team,position,planet='space'){const t=m.teams[team];if(!t||t.eliminated)return false;t.eliminated=true;t.hull=0;t.phase='eliminated';t.finished=true;const ids=[];for(const f of m.flags){if(f.owner===team&&(f.state==='onboard'||f.state==='carried')){const carried=f.state==='carried';f.state=planet==='B'?'ground':'wreck';f.planet=planet;f.position=carried?[...t.botPosition]:[...position];f.owner=null;f.carrier=null;ids.push(f.id);}}t.carrying=null;t.onboard=0;if(ids.length)m.wrecks.push({id:m.wrecks.length,team,position:[...position],planet,flags:ids});m.events.push({time:m.time,text:t.name+' crew eliminated; '+ids.length+' flags exposed for recovery.'});return true;}
export function damageCrew(m,team,damage,position,planet){const t=m.teams[team];if(!alive(m,team))return false;t.hull=Math.max(0,t.hull-Math.max(0,damage));if(t.hull<=0)eliminateCrew(m,team,position,planet);return true;}
export function departFrontier(m,team){const t=m.teams[team];if(!alive(m,team)||t.planet!=='B'||t.phase!=='surface'||t.carrying!==null)return false;t.phase='return';t.phaseTime=0;t.planet='space';return true;}
export function arriveHome(m,team){const t=m.teams[team];if(!alive(m,team))return false;t.phase='docked';t.phaseTime=0;t.planet='A';return true;}
export function finishMatch(m,reason='Match complete'){if(m.over)return;m.over=true;m.reason=reason;const scores=m.teams.map(t=>t.delivered),max=Math.max(...scores);const leaders=m.teams.filter(t=>t.delivered===max);m.winner=max>0&&leaders.length===1?leaders[0].id:null;}
function move(t,target,dt,speed=3.5){const d=dist(t.botPosition,target);if(d>.1){const k=Math.min(1,speed*dt/d);t.botPosition[0]+=(target[0]-t.botPosition[0])*k;t.botPosition[2]+=(target[2]-t.botPosition[2])*k;}return d;}
export function tickMatch(m,dt){if(m.over)return;const step=clamp(dt,0,.25);m.time+=step;for(const t of m.teams){if(t.id===0||t.eliminated)continue;t.elapsed+=step;t.phaseTime+=step;if(t.stun>0){t.stun=Math.max(0,t.stun-step);continue;}if(t.phase==='building'){t.progress=Math.min(.3,t.phaseTime/t.buildDuration*.3);if(t.phaseTime>=t.buildDuration){t.phase='systems test';t.phaseTime=0;}}else if(t.phase==='systems test'){t.progress=.3+t.phaseTime/18*.1;if(t.phaseTime>=18){t.phase='launching';t.phaseTime=0;}}else if(t.phase==='launching'){if(t.phaseTime>=6){t.phase='outbound';t.phaseTime=0;t.planet='space';}}else if(t.phase==='outbound'){t.progress=.4+Math.min(1,t.phaseTime/t.travelDuration)*.15;if(t.phaseTime>=t.travelDuration){t.phase='surface';t.phaseTime=0;t.planet='B';t.position=[...LANDING_BAYS[t.id]];t.botPosition=[...t.position];}}else if(t.phase==='surface'){t.progress=.55;const c=flagCounts(m,t.id);if(t.carrying!==null){if(move(t,t.position,step)<3.5)loadFlag(m,t.id,3,2);}else if(c.onboard>=3||(flagsAtSites(m)===0&&c.onboard>0)||t.phaseTime>145&&c.onboard>0){departFrontier(m,t.id);}else{let f=m.flags.find(f=>f.id===t.target&&['site','ground'].includes(f.state)&&f.planet==='B');if(!f){const available=m.flags.filter(f=>['site','ground'].includes(f.state)&&f.planet==='B');available.sort((a,b)=>dist(t.botPosition,a.position)-dist(t.botPosition,b.position));f=available[0];t.target=f?.id??null;}if(f){if(move(t,f.position,step,3.1)<2.2){if(f.state==='ground')recoverFlag(m,f.id,t.id,3,2);else scanFlag(m,f.id,t.id,3,step*.65,2,true,true);}}else if(c.onboard===0&&flagsAtSites(m)===0){t.phase='return';t.phaseTime=0;t.planet='space';}}}else if(t.phase==='return'){t.salvageCD=Math.max(0,(t.salvageCD||0)-step);if(t.phaseTime>20&&t.salvageCD<=0&&flagCounts(m,t.id).onboard<t.capacity){const f=m.flags.find(f=>f.state==='wreck'&&f.planet==='space');if(f&&recoverWreckFlag(m,f.id,t.id,1))t.salvageCD=3;}t.progress=.75+Math.min(1,t.phaseTime/60)*.15;if(t.phaseTime>=60){arriveHome(m,t.id);t.cycles++;}}else if(t.phase==='docked'){t.phase='delivering';t.phaseTime=0;}else if(t.phase==='delivering'){if(t.phaseTime>=1.5){t.phaseTime=0;deliverFlag(m,t.id,1);if(!flagCounts(m,t.id).onboard){t.phase='delivered';t.progress=1;t.finished=true;}}}}
const delivered=m.flags.filter(f=>f.state==='delivered').length,active=m.teams.filter(t=>!t.eliminated);if(delivered===12)finishMatch(m,'All twelve Science Flags delivered.');else if(!active.length)finishMatch(m,'All crews eliminated.');else if(m.time>=m.limit)finishMatch(m,'Mission window closed. Delivered flags determine the result.');else if(active.every(t=>['delivered','docked','delivering'].includes(t.phase))&&!m.flags.some(f=>f.state==='onboard'||f.state==='carried'))finishMatch(m,'All surviving crews have returned. Undelivered flags do not score.');}
export function scienceDebrief(m,team=0,systems={}){const c=flagCounts(m,team),t=m.teams[team],rank=1+m.teams.filter(t=>t.delivered>c.delivered).length;return {delivered:c.delivered,total:12,rank,victory:m.winner===team,eliminated:t.eliminated,xp:c.delivered*25+(t.eliminated?0:25),credits:c.delivered*20+(t.eliminated?0:10),patch:c.delivered>=7?'Frontier Vanguard':c.delivered>=3?'Orbital Pathfinder':'Flight Cadet',log:[{title:'FUEL RESERVE',value:Number.isFinite(systems.fuel)?systems.fuel.toFixed(1)+' kg':'Recorded',detail:'Departure mass and Δv determined the propellant cost. Return reserve had to remain available.'},{title:'POWER RECOVERED',value:Number.isFinite(systems.power)?systems.power.toFixed(1)+' kWh':'Recorded',detail:'A maintained power bus kept propulsion, scanning and life support available.'},{title:'SAFE RETURN',value:t.eliminated?'Crew eliminated':c.delivered+' flags delivered',detail:'Loading cargo did not score. Only flags transferred to Planet A earned points.'}]};}
